            aWandererA = aWandererA ^ ((RotL64(aScatter, 41U) + aOrbiterD) + RotL64(aOrbiterH, 29U));
            aWandererG = aWandererG + (((RotL64(aPrevious, 48U) + aOrbiterH) + RotL64(aOrbiterI, 5U)) + aNonceWordN);
            aWandererJ = aWandererJ ^ ((((RotL64(aCross, 19U) + aOrbiterC) + RotL64(aOrbiterK, 48U)) + RotL64(aCarry, 47U)) + aWUSaltG[((aIndex + 39U)) & S_SALT1]);
            aWandererE = aWandererE + (((RotL64(aIngress, 35U) + RotL64(aOrbiterK, 53U)) + aOrbiterF) + aWUSaltF[(((511U - aIndex) + 230U)) & S_SALT1]);
