            //
            aIngress = (RotL64(aKineticLaneC[((aIndex + 27342U)) & S_BLOCK1], 21U) ^ RotL64(aKineticLaneA[((aIndex + 28214U)) & S_BLOCK1], 10U));
            aIngress ^= RotL64(aCrystalLaneC[((S_BLOCK1 - aIndex + 28503U)) & S_BLOCK1], 39U);
