            aOrbiterC = ((aWandererG + RotL64(aIngress, 57U)) + 0x7F2DD68C6874744DULL) + aOASaltH[(((511U - aIndex) + 106U)) & S_SALT1];
            aOrbiterB = (aWandererA + RotL64(aScatter, 42U)) + 0x82540BD073C0A55BULL;
            aOrbiterF = ((aWandererH + RotL64(aPrevious, 37U)) + 0x65DC14571187998AULL) + aOASaltE[((aIndex + 231U)) & S_SALT1];
            aOrbiterJ = (((aWandererE + RotL64(aCross, 53U)) + RotL64(aCarry, 41U)) + 0x5389179ECBE5D5C8ULL) + aOASaltG[((aIndex + 117U)) & S_SALT1];
            aOrbiterI = (aWandererC + RotL64(aIngress, 11U)) + 0x68314EB919311A0AULL;
            aOrbiterG = ((aWandererI + RotL64(aScatter, 23U)) + 0x67BF8F8DF47C4503ULL) + aOASaltA[((aIndex + 367U)) & S_SALT1];
            aOrbiterE = (((aWandererB + RotL64(aPrevious, 47U)) + RotL64(aCarry, 51U)) + 0x305ED7F273A955A7ULL) + aNonceWordL;
            aOrbiterK = (aWandererK + RotL64(aCross, 26U)) + 0x21AC1EC5DB938612ULL;
