            aOrbiterB = (aOrbiterB ^ aOrbiterH) ^ 0x4111E132E3E92110ULL;
            aOrbiterB = RotL64((aOrbiterB * 0xBE3926EE2654F475ULL), 27U);
            //
            aOrbiterF = (aOrbiterF + aOrbiterJ) + 0xE29EB4942C5D68B0ULL;
            aOrbiterI = ((aOrbiterI ^ aOrbiterF) ^ 0xF58F744A0D267C67ULL) ^ aOUSaltG[(((511U - aIndex) + 13U)) & S_SALT1];
            aOrbiterI = RotL64((aOrbiterI * 0xA245B1EF9E5D3061ULL), 39U);
            //
            aOrbiterG = ((aOrbiterG + aOrbiterH) + 0x23CBF0B439E849FAULL) + aOUSaltA[(((511U - aIndex) + 261U)) & S_SALT1];
            aOrbiterE = ((aOrbiterE ^ aOrbiterG) ^ 0x253B999F46423A8CULL) ^ aNonceWordB;
            aOrbiterE = RotL64((aOrbiterE * 0x79A0F3911B9496A9ULL), 5U);
            //
            aOrbiterK = ((aOrbiterK + aOrbiterI) + 0x4EAF932F4617D947ULL) + aOUSaltC[(((511U - aIndex) + 498U)) & S_SALT1];
            aOrbiterD = ((aOrbiterD ^ aOrbiterK) ^ 0x10D4755285D1FAB5ULL) ^ aOUSaltH[((aIndex + 139U)) & S_SALT1];
            aOrbiterD = RotL64((aOrbiterD * 0x5596E72E345599F9ULL), 35U);
            //
            aOrbiterA = (aOrbiterA + aOrbiterE) + 0x7EE10837BE5F3494ULL;
            aOrbiterC = (aOrbiterC ^ aOrbiterA) ^ 0xA2E774381E9172A1ULL;
            aOrbiterC = RotL64((aOrbiterC * 0xDE1CC25EC71F8D79ULL), 3U);
            //
            aOrbiterB = (aOrbiterB + aOrbiterD) + 0xD5E3AC18F2CABFAEULL;
            aOrbiterJ = (aOrbiterJ ^ aOrbiterB) ^ 0x1760F679B97DEDD2ULL;
