            //
            aOrbiterJ = ((aOrbiterJ + aOrbiterG) + 0x41E51E54D8783247ULL) + aOUSaltD[((aIndex + 83U)) & S_SALT1];
            aOrbiterH = (aOrbiterH ^ aOrbiterJ) ^ 0xC3173743E8EF0106ULL;
