            aWandererA = aWandererA ^ ((((RotL64(aScatter, 3U) + RotL64(aOrbiterK, 41U)) + aOrbiterA) + RotL64(aCarry, 23U)) + aNonceWordJ);
            aWandererB = aWandererB + ((((RotL64(aPrevious, 35U) + aOrbiterF) + RotL64(aOrbiterB, 5U)) + aNonceWordP) + aWUSaltB[(((511U - aIndex) + 137U)) & S_SALT1]);
            aWandererJ = aWandererJ ^ ((RotL64(aCross, 43U) + aOrbiterE) + RotL64(aOrbiterJ, 35U));
            aWandererG = aWandererG + (((RotL64(aIngress, 11U) + aOrbiterD) + RotL64(aOrbiterF, 53U)) + aWUSaltD[((aIndex + 62U)) & S_SALT1]);
            aWandererE = aWandererE ^ ((RotL64(aScatter, 5U) + RotL64(aOrbiterH, 46U)) + aOrbiterD);
            aWandererD = aWandererD + ((((RotL64(aPrevious, 53U) + RotL64(aOrbiterI, 11U)) + aOrbiterE) + aNonceWordA) + aWUSaltE[(((511U - aIndex) + 294U)) & S_SALT1]);
            aWandererK = aWandererK ^ (((RotL64(aCross, 58U) + aOrbiterC) + RotL64(aOrbiterG, 19U)) + RotL64(aCarry, 43U));
