            //
            aIngress = (RotL64(aShadowLaneD[((aIndex + 7740U)) & S_BLOCK1], 27U) ^ RotL64(aShadowLaneB[((aIndex + 6884U)) & S_BLOCK1], 5U));
            aIngress ^= (RotL64(aIceLaneB[((aIndex + 1178U)) & S_BLOCK1], 43U) ^ RotL64(aCrystalLaneD[((S_BLOCK1 - aIndex + 2458U)) & S_BLOCK1], 56U));
