            //
            aOrbiterI = (aOrbiterI + aOrbiterA) + 0x725698EB6991C964ULL;
            aOrbiterG = (aOrbiterG ^ aOrbiterI) ^ 0x5FB6E6199A95175FULL;
            aOrbiterG = RotL64((aOrbiterG * 0xC7AD5EEDEED5B407ULL), 35U);
            //
            aOrbiterD = (aOrbiterD + aOrbiterF) + 0x071CF0C8364BE62CULL;
            aOrbiterE = (aOrbiterE ^ aOrbiterD) ^ 0x45B48BEE16AB0785ULL;
            aOrbiterE = RotL64((aOrbiterE * 0xF586603A4CD4BC07ULL), 23U);
            //
            aOrbiterH = (aOrbiterH + aOrbiterB) + 0xA748F09090E776ADULL;
            aOrbiterJ = ((aOrbiterJ ^ aOrbiterH) ^ 0x97BA26038CAA3141ULL) ^ aOUSaltE[((aIndex + 143U)) & S_SALT1];
            aOrbiterJ = RotL64((aOrbiterJ * 0xDE0F5479E8726573ULL), 51U);
