            aOrbiterC = (aOrbiterC + aOrbiterK) + 0xF6DC2494DCD8CFC4ULL;
            aOrbiterA = (aOrbiterA ^ aOrbiterC) ^ 0x4DDDACC53AED6BCFULL;
            aOrbiterA = RotL64((aOrbiterA * 0xC0F2066676C7CF1DULL), 5U);
