            aWandererD = aWandererD + (((RotL64(aCross, 29U) + RotL64(aOrbiterC, 11U)) + aOrbiterK) + aWUSaltB[((aIndex + 22U)) & S_SALT1]);
            aWandererB = aWandererB ^ ((RotL64(aIngress, 47U) + RotL64(aOrbiterA, 56U)) + aOrbiterD);
            //
            aCarry = aCarry + (aWandererG ^ RotL64(aWandererJ, 53U));
