            aOrbiterB = (aOrbiterB + aOrbiterE) + 0x6B42E0E2B0DC5BC4ULL;
            aOrbiterC = ((aOrbiterC ^ aOrbiterB) ^ 0x8C1C727DEDEFC041ULL) ^ aOUSaltC[((aIndex + 109U)) & S_SALT1];
            aOrbiterC = RotL64((aOrbiterC * 0x4D9390EB099A1CBDULL), 47U);
            //
            aOrbiterG = (aOrbiterG + aOrbiterH) + 0x29CC1F735A93BF43ULL;
