            aOrbiterA = ((aWandererA + RotL64(aScatter, 29U)) + RotL64(aCarry, 21U)) + 0x16A20240732268C4ULL;
            aOrbiterD = (aWandererJ + RotL64(aPrevious, 27U)) + 0x71F6185E5D1BD82AULL;
            aOrbiterH = (aWandererG + RotL64(aCross, 13U)) + 0x6586689C7DCAD1B2ULL;
