            aOrbiterE = (aOrbiterE + aOrbiterJ) + 0x2D83CE704CDD375DULL;
            aOrbiterI = (aOrbiterI ^ aOrbiterE) ^ 0xECAADB8EB7C15EB6ULL;
            aOrbiterI = RotL64((aOrbiterI * 0xC52D21465CC3D08BULL), 39U);
            //
