            aOrbiterK = (aOrbiterK + aOrbiterA) + 0x4B13304DDDCDABD8ULL;
            aOrbiterF = ((aOrbiterF ^ aOrbiterK) ^ 0xBE9DD95637B869DBULL) ^ aOUSaltE[(((511U - aIndex) + 287U)) & S_SALT1];
