            //
            aOrbiterB = (aOrbiterB + aOrbiterG) + 0x911337650A817DEAULL;
            aOrbiterH = ((aOrbiterH ^ aOrbiterB) ^ 0xA28BCFE37CFCA96FULL) ^ aOUSaltH[(((511U - aIndex) + 160U)) & S_SALT1];
            aOrbiterH = RotL64((aOrbiterH * 0xD237E081A222B935ULL), 3U);
