            //
            aOrbiterJ = ((aOrbiterJ + aOrbiterD) + 0x726350B72D8F1FBBULL) + aOUSaltF[(((511U - aIndex) + 478U)) & S_SALT1];
            aOrbiterI = (aOrbiterI ^ aOrbiterJ) ^ 0xC6BA12A36ABB5AF1ULL;
