            //
            aOrbiterD = (aWandererJ + RotL64(aCross, 3U)) + 0x1C521B0CC925F437ULL;
            aOrbiterI = ((aWandererE + RotL64(aIngress, 41U)) + RotL64(aCarry, 47U)) + 0x908F64E1FCF18982ULL;
            aOrbiterC = (aWandererK + RotL64(aScatter, 34U)) + 0x8B61A6A3C4A1209FULL;
            aOrbiterF = (aWandererF + RotL64(aPrevious, 5U)) + 0x711F99B1F234CA03ULL;
            aOrbiterB = ((aWandererG + RotL64(aCross, 51U)) + RotL64(aCarry, 53U)) + 0x1CCAEF34789A9FC4ULL;
            aOrbiterH = (aWandererC + RotL64(aIngress, 19U)) + 0x0CFC7276BE9AA14BULL;
            aOrbiterE = (aWandererB + RotL64(aScatter, 39U)) + 0x57EEB85FC951B09DULL;
            aOrbiterJ = ((aWandererD + RotL64(aPrevious, 27U)) + 0x7A572AEED4494F32ULL) + aOASaltC[(((511U - aIndex) + 421U)) & S_SALT1];
            aOrbiterA = (((aWandererH + RotL64(aCross, 37U)) + RotL64(aCarry, 3U)) + 0x10C59BDA1A580AB5ULL) + aOASaltF[(((511U - aIndex) + 125U)) & S_SALT1];
            aOrbiterG = (aWandererA + RotL64(aIngress, 53U)) + 0x51780AA90B28E443ULL;
            aOrbiterK = ((aWandererI + RotL64(aScatter, 48U)) + 0x527B263A853E654FULL) + aOASaltH[((aIndex + 59U)) & S_SALT1];
            //
            aOrbiterD = (aOrbiterD + aOrbiterI) + 0xB753966B5A952E3BULL;
            aOrbiterC = ((aOrbiterC ^ aOrbiterD) ^ 0x8B7D4D0D878A4B11ULL) ^ aOUSaltF[(((511U - aIndex) + 480U)) & S_SALT1];
            aOrbiterC = RotL64((aOrbiterC * 0xC43251F6752E3B01ULL), 5U);
            //
            aOrbiterF = (aOrbiterF + aOrbiterB) + 0xD09CBF14647424EAULL;
            aOrbiterH = (aOrbiterH ^ aOrbiterF) ^ 0xE504957679CE8AA2ULL;
            aOrbiterH = RotL64((aOrbiterH * 0x4FB14D110E63D241ULL), 11U);
            //
            aOrbiterE = (aOrbiterE + aOrbiterJ) + 0xD0A0395C2F4B41DDULL;
            aOrbiterA = (aOrbiterA ^ aOrbiterE) ^ 0x72D66E1D5CAB0312ULL;
            aOrbiterA = RotL64((aOrbiterA * 0x9AAF6219057227E3ULL), 57U);
            //
            aOrbiterG = ((aOrbiterG + aOrbiterH) + 0x988B2978BD852595ULL) + aOUSaltG[((aIndex + 76U)) & S_SALT1];
            aOrbiterD = (aOrbiterD ^ aOrbiterG) ^ 0x71F5DB1C57CBCEE8ULL;
            aOrbiterD = RotL64((aOrbiterD * 0xB4ADBB236AB1695BULL), 13U);
            //
            aOrbiterK = (aOrbiterK + aOrbiterC) + 0x45844F23F26DB7C9ULL;
            aOrbiterF = ((aOrbiterF ^ aOrbiterK) ^ 0xDC54869C95E15C14ULL) ^ aOUSaltH[((aIndex + 493U)) & S_SALT1];
            aOrbiterF = RotL64((aOrbiterF * 0x3E947B6594ED995DULL), 29U);
            //
            aOrbiterJ = (aOrbiterJ + aOrbiterA) + 0xC0961B6D1A30D0D3ULL;
            aOrbiterI = (aOrbiterI ^ aOrbiterJ) ^ 0x76808CC260EB1815ULL;
            aOrbiterI = RotL64((aOrbiterI * 0x2B83F17595FCBE55ULL), 47U);
            //
            aOrbiterB = (aOrbiterB + aOrbiterG) + 0xBCBD959F552F0785ULL;
            aOrbiterK = (aOrbiterK ^ aOrbiterB) ^ 0xF7ADBF6FC4978C17ULL;
            aOrbiterK = RotL64((aOrbiterK * 0x6B1395A2D59124C5ULL), 35U);
            //
            aOrbiterI = (aOrbiterI + aOrbiterF) + 0xC69A0CD6F501CB35ULL;
            aOrbiterE = (aOrbiterE ^ aOrbiterI) ^ 0x796E1BF510CD52DBULL;
            aOrbiterE = RotL64((aOrbiterE * 0xE1910DE33D571955ULL), 27U);
            //
            aOrbiterH = (aOrbiterH + aOrbiterD) + 0x579AEA5FC7CC1FA4ULL;
            aOrbiterJ = (aOrbiterJ ^ aOrbiterH) ^ 0x92CC87A70F693018ULL;
            aOrbiterJ = RotL64((aOrbiterJ * 0x4CAECB78F03F182FULL), 41U);
            //
            aOrbiterC = (aOrbiterC + aOrbiterE) + 0xFB254F6A4521CA69ULL;
            aOrbiterG = (aOrbiterG ^ aOrbiterC) ^ 0xFDF0D72FE15E50ADULL;
            aOrbiterG = RotL64((aOrbiterG * 0x192743D348939977ULL), 3U);
            //
            aOrbiterA = ((aOrbiterA + aOrbiterK) + 0x55C6EBE1BA16B86BULL) + aOUSaltC[(((511U - aIndex) + 149U)) & S_SALT1];
            aOrbiterB = ((aOrbiterB ^ aOrbiterA) ^ 0x0D46384A84424ACAULL) ^ aOUSaltB[(((511U - aIndex) + 408U)) & S_SALT1];
            aOrbiterB = RotL64((aOrbiterB * 0x644A704A8988B027ULL), 19U);
            //
            aIngress = RotL64(aOrbiterD, 24U) ^ aOrbiterG;
            aIngress = aIngress + (RotL64(aOrbiterE, 11U) ^ aOrbiterC);
            aIngress = aIngress + (aOrbiterI ^ RotL64(aOrbiterA, 21U));
            aIngress = aIngress + (RotL64(aOrbiterJ, 29U) ^ aOrbiterF);
            aIngress = aIngress + (RotL64(aOrbiterH, 35U) ^ aOrbiterK);
            aIngress = aIngress + RotL64(aOrbiterB, 41U);
