            aOrbiterH = ((aWandererE + RotL64(aScatter, 19U)) + RotL64(aCarry, 5U)) + 0xF5E25788A1BA13F2ULL;
            aOrbiterD = ((aWandererJ + RotL64(aPrevious, 21U)) + 0xF60F65B89638DD23ULL) + aOASaltH[(((511U - aIndex) + 375U)) & S_SALT1];
