            aOrbiterF = (aWandererB + RotL64(aCross, 26U)) + 0xB7968B0F4E77A2ADULL;
            aOrbiterB = ((aWandererG + RotL64(aIngress, 37U)) + RotL64(aCarry, 51U)) + 0x71FA958FC7B5093CULL;
