            //
            aOrbiterB = ((aOrbiterB + aOrbiterH) + 0x926CD7D940BB392AULL) + aOUSaltD[((aIndex + 57U)) & S_SALT1];
            aOrbiterG = ((aOrbiterG ^ aOrbiterB) ^ 0x2EA8131737E44060ULL) ^ aOUSaltE[((aIndex + 108U)) & S_SALT1];
            aOrbiterG = RotL64((aOrbiterG * 0xE0B016679FC7F7D1ULL), 5U);
            //
            aOrbiterC = ((aOrbiterC + aOrbiterK) + 0x1DC387F319D16CD9ULL) + aOUSaltG[((aIndex + 502U)) & S_SALT1];
            aOrbiterJ = ((aOrbiterJ ^ aOrbiterC) ^ 0x6F033BEA7122DCC4ULL) ^ aOUSaltC[(((511U - aIndex) + 63U)) & S_SALT1];
            aOrbiterJ = RotL64((aOrbiterJ * 0xEDD5BAF885E5AB15ULL), 51U);
            //
            aOrbiterF = (aOrbiterF + aOrbiterB) + 0x339AF7325941368BULL;
            aOrbiterI = (aOrbiterI ^ aOrbiterF) ^ 0xF32C31434168C5F9ULL;
