            aWandererA = aWandererA + ((RotL64(aPrevious, 37U) + RotL64(aOrbiterJ, 6U)) + aOrbiterI);
            aWandererG = aWandererG ^ (((RotL64(aCross, 23U) + aOrbiterG) + RotL64(aOrbiterE, 51U)) + aWUSaltH[((aIndex + 213U)) & S_SALT1]);
