            aOrbiterE = ((aWandererA + RotL64(aPrevious, 47U)) + RotL64(aCarry, 43U)) + 0xFD1E3B4B3BA42F41ULL;
            aOrbiterK = (aWandererD + RotL64(aCross, 51U)) + 0x61DD3763A40FAC51ULL;
            aOrbiterH = ((aWandererH + RotL64(aIngress, 19U)) + 0x7AFBE6D4E21F378CULL) + aOASaltB[(((511U - aIndex) + 206U)) & S_SALT1];
            aOrbiterD = (((aWandererB + RotL64(aScatter, 3U)) + RotL64(aCarry, 3U)) + 0xC7CA9FD2169D4CF5ULL) + aOASaltE[(((511U - aIndex) + 295U)) & S_SALT1];
