            //
            aOrbiterE = ((aOrbiterE + aOrbiterK) + 0x711935706B6EA676ULL) + aOUSaltE[((aIndex + 389U)) & S_SALT1];
            aOrbiterH = (aOrbiterH ^ aOrbiterE) ^ 0xD24B2DAF36E8AEA4ULL;
